{
  "name": "晶格图形标注对象",
  "name_en": "Lattice Graphic Overlay",
  "manufacturer": "Nion",
  "description": "这不是独立实验硬件，而是显微图像或衍射图分析界面中的晶格图形标注对象，用于在图像上定义周期性晶格区域、掩膜或测量参考，并可交互调整 u、v 方向位置与半径。",
  "description_en": "This is not a standalone laboratory instrument but a lattice graphic overlay used in microscopy or diffraction image analysis interfaces. It is used to define periodic lattice regions, masks, or measurement references on images, with interactive control of the u position, v position, and radius.",
  "tag_hints": [
    "lattice ROI",
    "image annotation",
    "microscopy image analysis",
    "diffraction pattern analysis",
    "interactive graphic overlay",
    "mask generation"
  ],
  "actions": [
    {
      "action_name": "auto-u_pos",
      "description": "获取/设置/定义晶格的 u 方向位置。",
      "description_en": "Get/set/define the lattice u-direction position."
    },
    {
      "action_name": "auto-v_pos",
      "description": "获取/设置/定义晶格的 v 方向位置。",
      "description_en": "Get/set/define the lattice v-direction position."
    },
    {
      "action_name": "auto-radius",
      "description": "获取/设置/定义晶格半径。",
      "description_en": "Get/set/define the lattice radius."
    },
    {
      "action_name": "auto-mime_data_dict",
      "description": "将晶格图形导出为 MIME 数据字典。",
      "description_en": "Export the lattice graphic as a MIME data dictionary."
    },
    {
      "action_name": "auto-read_from_mime_data",
      "description": "从 MIME 数据字典读取并恢复晶格图形。",
      "description_en": "Read and restore the lattice graphic from a MIME data dictionary."
    },
    {
      "action_name": "auto-test",
      "description": "测试给定点命中了晶格图形的哪一部分。",
      "description_en": "Test which part of the lattice graphic is hit at a given point."
    },
    {
      "action_name": "auto-begin_drag",
      "description": "开始拖动或编辑晶格图形。",
      "description_en": "Begin dragging or editing the lattice graphic."
    },
    {
      "action_name": "auto-end_drag",
      "description": "结束拖动或编辑晶格图形。",
      "description_en": "End dragging or editing the lattice graphic."
    },
    {
      "action_name": "auto-adjust_part",
      "description": "在交互拖动过程中调整晶格图形的选定部分。",
      "description_en": "Adjust the selected part of the lattice graphic during interactive dragging."
    },
    {
      "action_name": "auto-label_position",
      "description": "获取晶格图形标签的位置。",
      "description_en": "Get the position of the lattice graphic label."
    }
  ]
}

